changeSet.sql:
ALTER TABLE cmr_strategy
    ADD COLUMN preset TINYINT(1) NOT NULL DEFAULT 0 COMMENT '系统预置（不可下线）' AFTER status,
    ADD COLUMN offline_reason VARCHAR(32) COMMENT '下线原因 tuning/poor/replaced/other',
    ADD COLUMN offline_time DATETIME COMMENT '下线时间';
UPDATE cmr_strategy SET preset = 1 WHERE scene = 'all';
